# Generated by the MCRI team.
#
# Variant observation counts, stage 3: narrow every `gt_stats_dict` attribute from
# UInt32 to UInt16, halving the dictionary's resident memory.
#
# These columns hold a count bounded by the cohort (`ac_* <= 2 x individuals`,
# `hom_* <= individuals`), so UInt16 is EXACT, not lossy, below 32,768 individuals.
#
# The clamp is not optional. A dictionary attribute narrower than its source column
# truncates MODULARLY and SILENTLY -- a source value of 70,000 reads back as 4,464, which
# is indistinguishable from a real rare-variant count. Sourcing via QUERY with
# `least(col, 65535)` makes an over-range value saturate at 65,535 instead, so it shows up
# as an implausibly round ceiling rather than a plausible small number.
#
# The `gt_stats` TABLE stays UInt32: it is on disk, exactness is preserved there, and
# SummingMergeTree merges stay safe. Only the in-memory copy is narrowed.
import os
from string import Template

from django.db import migrations

from settings import DATABASES

# A QUERY source is NOT resolved against the dictionary's own database the way a TABLE
# source is, and a DB clause is IGNORED when QUERY is supplied (both verified: the
# dictionary loads as FAILED with UNKNOWN_TABLE). The table must be qualified inside
# the query itself.
CLICKHOUSE_DATABASE = DATABASES.get('clickhouse_write', {}).get('NAME', 'seqr')

CLICKHOUSE_WRITER_PASSWORD = os.environ.get('CLICKHOUSE_WRITER_PASSWORD', 'clickhouse_test')
CLICKHOUSE_WRITER_USER = os.environ.get('CLICKHOUSE_WRITER_USER', 'clickhouse')

UINT16_MAX = 65535

GT_STATS_DICT = Template(Template("""
CREATE DICTIONARY `$reference_genome/$dataset_type/gt_stats_dict`
(
    key UInt32,
    $columns
)
PRIMARY KEY key
SOURCE(CLICKHOUSE(USER '$clickhouse_writer_user' PASSWORD '$clickhouse_writer_password' QUERY '$query'))
LIFETIME(MIN 0 MAX 0)
LAYOUT(FLAT(MAX_ARRAY_SIZE $size))
""").safe_substitute(
    clickhouse_writer_user=CLICKHOUSE_WRITER_USER,
    clickhouse_writer_password=CLICKHOUSE_WRITER_PASSWORD,
))

# The pre-migration (0016) definition, for the reverse operation.
LEGACY_GT_STATS_DICT = Template(Template("""
CREATE DICTIONARY `$reference_genome/$dataset_type/gt_stats_dict`
(
    key UInt32,
    $columns
)
PRIMARY KEY key
SOURCE(CLICKHOUSE(USER '$clickhouse_writer_user' PASSWORD '$clickhouse_writer_password' TABLE `$reference_genome/$dataset_type/gt_stats`))
LIFETIME(MIN 0 MAX 0)
LAYOUT(FLAT(MAX_ARRAY_SIZE $size))
""").safe_substitute(
    clickhouse_writer_user=CLICKHOUSE_WRITER_USER,
    clickhouse_writer_password=CLICKHOUSE_WRITER_PASSWORD,
))

SNV_INDEL_COLS = ['ac_wes', 'ac_wgs', 'ac_affected', 'hom_wes', 'hom_wgs', 'hom_affected']
MITO_COLS = ['ac_het_wes', 'ac_het_wgs', 'ac_het_affected', 'ac_hom_wes', 'ac_hom_wgs', 'ac_hom_affected']
SV_COLS = ['ac_wgs', 'ac_affected', 'hom_wgs', 'hom_affected']

DICTIONARIES = [
    ('GRCh37', 'SNV_INDEL', SNV_INDEL_COLS, int(2e8)),
    ('GRCh38', 'SNV_INDEL', SNV_INDEL_COLS, int(1e9)),
    ('GRCh38', 'MITO', MITO_COLS, int(1e6)),
    ('GRCh38', 'SV', SV_COLS, int(5e6)),
]


def _clamped_query(reference_genome, dataset_type, columns):
    # Saturating cast. Note the single quotes around the QUERY in the DDL, so no
    # single quotes may appear here.
    projected = ', '.join(f'least({c}, {UINT16_MAX}) AS {c}' for c in columns)
    return (
        f'SELECT key, {projected} '
        f'FROM {CLICKHOUSE_DATABASE}.`{reference_genome}/{dataset_type}/gt_stats`'
    )


def _operations():
    operations = []
    for reference_genome, dataset_type, columns, size in DICTIONARIES:
        drop = f'DROP DICTIONARY IF EXISTS `{reference_genome}/{dataset_type}/gt_stats_dict`'
        forward = GT_STATS_DICT.substitute(
            reference_genome=reference_genome,
            dataset_type=dataset_type,
            columns=',\n    '.join(f'{c} UInt16' for c in columns),
            query=_clamped_query(reference_genome, dataset_type, columns),
            size=size,
        )
        backward = LEGACY_GT_STATS_DICT.substitute(
            reference_genome=reference_genome,
            dataset_type=dataset_type,
            columns=',\n    '.join(f'{c} UInt32' for c in columns),
            size=size,
        )
        operations.append(migrations.RunSQL(drop, drop, hints={'clickhouse': True}))
        operations.append(migrations.RunSQL(forward, backward, hints={'clickhouse': True}))
    return operations


class Migration(migrations.Migration):

    dependencies = [
        ('clickhouse_search', '0024_counted_sample_dict'),
    ]

    operations = _operations()
